.gallery-page .grid2{gap:20px 14px}.gallery-page .card{min-width:0;border-radius:16px;box-shadow:none}.asset-image{position:relative;overflow:hidden;background:var(--nn-soft)}.asset-image .photo{width:100%;height:auto;aspect-ratio:1;object-fit:contain}.template-cover{width:100%;height:auto;aspect-ratio:3/4}.asset-source{position:absolute;left:8px;top:8px;max-width:calc(100% - 52px);padding:4px 7px;border-radius:6px;background:#fcfbf5ed;color:var(--nn-muted);font-size:10px;line-height:1.5}.favorite{position:absolute;right:4px;top:4px;width:44px;height:44px;min-height:44px;padding:0;background:#fcfbf5b3;border-radius:50%;font-size:23px}.favorite svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}.favorite-active{color:var(--nn-accent)}.favorite-active svg{fill:currentColor}.card-info{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px 4px;padding:16px 12px 12px}.card-info .h3{grid-column:1/-1;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;white-space:normal;overflow-wrap:anywhere;line-height:1.6;font-size:13px;margin:0 4px}.card-info .quiet-button{justify-self:start;justify-content:center;grid-row:2;grid-column:1;min-height:44px;max-width:100%;padding:8px;color:var(--nn-accent);font-size:12px;white-space:nowrap}.delete-material{grid-row:2;grid-column:2;min-width:44px;min-height:44px;padding:8px;background:transparent;color:var(--nn-danger);font-size:12px}
.pending-bar,.batch-bar{margin-top:16px;padding:12px 16px;background:var(--nn-soft);border-radius:14px;font-size:13px}.pending-strip{white-space:nowrap;margin:8px 0}.pending-strip img{display:inline-block;width:60px;height:60px;margin-right:8px;border-radius:8px}.filter-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.filter-options button{font-size:13px}.selected-filter{background:var(--nn-selected);color:var(--nn-accent)}.filter-unfiled{width:100%;margin-top:16px}
.cutout-preview{background-color:var(--nn-panel);background-image:linear-gradient(45deg,#e9ede3 25%,transparent 25%,transparent 75%,#e9ede3 75%),linear-gradient(45deg,#e9ede3 25%,transparent 25%,transparent 75%,#e9ede3 75%);background-size:18px 18px;background-position:0 0,9px 9px}
@container(max-width:300px){.embedded-library .grid2{grid-template-columns:1fr}}
@container(min-width:650px){.gallery-page .grid2{grid-template-columns:repeat(3,minmax(0,1fr))}}
@container(min-width:900px){.gallery-page .grid2{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:360px){.gallery-page .grid2{gap:12px 10px}.card-info{padding:12px 8px 8px}.card-info .quiet-button{font-size:11px;padding:8px 4px}.delete-material{padding:8px 4px;font-size:11px}}
</style>
